class Box {
    int v;
    Box(int v) { this.v = v; }
}
public class Main {
    static void swap(Box a, Box b) {
        Box t = a;
        a = b;
        b = t;
        a.v = 99;
    }
    public static void main(String[] args) {
        Box x = new Box(1), y = new Box(2);
        swap(x, y);
        System.out.println(x.v + " " + y.v);
    }
}

