public class Main {
    public static void main(String[] args) {
        try {
            int[] a = new int[2];
            a[2] = 5;
            System.out.print("A ");
        } catch (ArithmeticException e) {
            System.out.print("B ");
        } catch (RuntimeException e) {
            System.out.print("C ");
        } catch (Exception e) {
            System.out.print("D ");
        } finally {
            System.out.print("E ");
        }
        System.out.print("F");
    }
}

public class Main {
    static int f() {
        try {
            throw new IllegalStateException();
        } catch (RuntimeException e) {
            return 1;
        } finally {
            System.out.print("F ");
        }
    }
    public static void main(String[] args) {
        System.out.println(f());
    }
}

public class Main {
