        } catch (Exception e) {
            System.out.print("E ");
        } finally {
            System.out.print("F ");
        }
        System.out.print("After");
    }
}

class Base {
    Base() { describe(); }
    void describe() { System.out.println("Base"); }
}
class Derived extends Base {
    private String name = "D";
    private int n = 5;
    Derived() { super(); describe(); }
    @Override
    void describe() { System.out.println(name + " " + n); }
}
public class Main {
    public static void main(String[] args) {
        new Derived();
    }
}

